INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT110-S2-Q18$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Opposing Point$batch10$, $batch10$Radical environmentalists' positions often contain false hypotheses and economically infeasible proposals.$batch10$), (1, $batch10$Conclusion$batch10$, $batch10$Even these extremists play a positive role.$batch10$), (2, $batch10$Evidence$batch10$, $batch10$Inertia on environmental issues is so stubborn that progress happens only if people fear environmental disaster, however ill-founded the fear.$batch10$), (3, $batch10$Evaluate$batch10$, $batch10$"But there is a positive role" is the pivot, and "for" introduces the support. What is the positive role? Radicals create the fear that makes progress possible. So the conclusion is that radicals, by pushing their views, help bring about progress.$batch10$), (4, $batch10$Goal$batch10$, $batch10$Radical environmentalists play a positive role by stimulating progress.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT110-S2-Q18$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$The editorialist doesn't say how much progress has been made, or that it is mainly due to radicals. The claim is only that radicals play a positive role.$batch10$), ($batch10$B$batch10$, $batch10$This states the positive role: by promoting their views, radicals help produce progress. That is the claim the "for" clause supports.$batch10$), ($batch10$C$batch10$, $batch10$This restates the evidence about fear and inertia, and adds "most effectively," which the passage doesn't say.$batch10$), ($batch10$D$batch10$, $batch10$This is the most-picked trap. It says radicals put forth untenable positions in order to produce fear. The editorialist never says the radicals intend this. They have a positive effect, whatever their motives.$batch10$), ($batch10$E$batch10$, $batch10$This overstates the concession at the start. It's the part the author grants before the "but."$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT110-S2-Q18$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
